  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Rates Watch Data",
    "url": "http://localhost:7803",
    "widgets_json": {
      "rates_auctions_table": {
        "name": "Rates Auctions Table",
        "description": "Upcoming auctions and demand metrics.",
        "endpoint": "/rates-auctions-table",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "auction_date",
            "type": "text",
            "label": "Auction Date",
            "value": "2026-07-14",
            "description": "Rates Auctions Table focus field."
          }
        ],
        "data": {
          "defaultSymbol": "rates-auctions-table"
        }
      },
      "curve_spread_metric": {
        "name": "2s10s Spread",
        "description": "Current 2s10s spread in bps.",
        "endpoint": "/curve-spread",
        "type": "metric",
        "gridData": {
          "w": 6,
          "h": 4
        }
      }
    },
    "apps_json": [
      {
        "name": "Rates Auctions",
        "description": "Auction calendar and curve spread.",
        "tabs": {
          "auctions": {
            "id": "auctions",
            "name": "Auctions",
            "layout": [
              {
                "i": "rates_auctions_table",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "spread": {
            "id": "spread",
            "name": "Spread",
            "layout": [
              {
                "i": "curve_spread_metric",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        }
      }
    ]
  }
}

